function containsDuplicate(nums) {
  const sorted = [...nums].sort((a, b) => a - b);   // equal values end up side by side
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i] === sorted[i - 1]) return true;   // a value equal to its neighbour
  }
  return false;
}

def contains_duplicate(nums):
    s = sorted(nums)                      # equal values end up side by side
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:              # a value equal to its neighbour
            return True
    return False

boolean containsDuplicate(int[] nums) {
    int[] sorted = nums.clone();
    Arrays.sort(sorted);                          // equal values end up side by side
    for (int i = 1; i < sorted.length; i++) {
        if (sorted[i] == sorted[i - 1]) return true;   // a value equal to its neighbour
    }
    return false;
}

bool containsDuplicate(vector<int>& nums) {
    vector<int> sorted = nums;
    sort(sorted.begin(), sorted.end());           // equal values end up side by side
    for (size_t i = 1; i < sorted.size(); i++) {
        if (sorted[i] == sorted[i - 1]) return true;   // a value equal to its neighbour
    }
    return false;
}

function containsDuplicate(nums) {
  const seen = new Set();
  for (const x of nums) {
    if (seen.has(x)) return true;                 // seen before: a duplicate
    seen.add(x);
  }
  return false;
}

boolean containsDuplicate(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    for (int x : nums) {
        if (!seen.add(x)) return true;            // add() is false when it was already there
    }
    return false;
}

bool containsDuplicate(vector<int>& nums) {
    unordered_set<int> seen;
    for (int x : nums) {
        if (!seen.insert(x).second) return true;  // already there: a duplicate
    }
    return false;
}
